import type { proto } from '@whiskeysockets/baileys';
export interface StoredEvent { id: string; chat: string; sender: string; timestamp: number; kind: 'message' | 'edited' | 'deleted' | 'view-once' | 'reaction'; text?: string; mediaType?: string; before?: string; after?: string; }
export class EventStore { private readonly events = new Map<string, StoredEvent>(); constructor(private readonly maxTotal = 2000, private readonly ttlMs = 86_400_000) {} add(event: StoredEvent) { this.prune(); if (this.events.size >= this.maxTotal) this.events.delete(this.events.keys().next().value as string); this.events.set(event.id, event); } get(id: string) { this.prune(); return this.events.get(id); } forChat(chat: string) { this.prune(); return [...this.events.values()].filter(event => event.chat === chat).sort((a, b) => a.timestamp - b.timestamp); } markEdited(id: string, after: string) { const event = this.events.get(id); if (event) { event.kind = 'edited'; event.before = event.text; event.after = after; } } markDeleted(id: string) { const event = this.events.get(id); if (event) event.kind = 'deleted'; } private prune() { const cutoff = Date.now() - this.ttlMs; for (const [id, event] of this.events) if (event.timestamp < cutoff) this.events.delete(id); } }
export const eventStore = new EventStore();
export const messageId = (message: proto.IWebMessageInfo) => message.key?.id ?? `${Date.now()}-${Math.random()}`;
